    """Write a function that returns true if the given number is the multiplication of 3 prime numbers
    and false otherwise.
    Knowing that (a) is less then 100. 
    Example:
    is_multiply_prime(30) == True
    30 = 2 * 3 * 5
    """
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n ** 0.5) + 1):
            if n % i == 0:
                return False
        return True

    def is_multiply_prime_helper(n, primes):
        if len(primes) == 3:
            return n == 1
        for p in range(2, n + 1):
            if is_prime(p):
                if is_multiply_prime_helper(n // p, primes + [p]):
                    return True
        return False

    return is_multiply_prime_helper(a, [])

